/**
 * Look up a UI string by key for the given language, optionally substituting
 * {placeholder} tokens with values from `vars`.
 */
export function t(
  key: keyof typeof UI,
  lang: Lang,
  vars?: Record<string, string | number>,
): string {
  const entry = UI[key];
  if (!entry) {
    console.warn(`Missing UI translation for key: ${String(key)}`);
    return String(key);
  }
  let text = lang === "af" ? entry.af : entry.en;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      text = text.replaceAll(`{${k}}`, String(v));
    }
  }
  return text;
}
